import { Link } from 'react-router-dom';
import { Sparkles, Compass } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { useLanguage } from '@/components/layout/LanguageProvider';
import { siteConfig } from '@/config/site.config';

const MODES = [
  { id: 'content-creation', icon: '🎬' },
  { id: 'learn-skill', icon: '📚' },
  { id: 'channel-strategy', icon: '📊' },
  { id: 'idea-evaluation', icon: '🔍' },
  { id: 'custom', icon: '🎛️' },
] as const;

export default function HomePage() {
  const { t } = useLanguage();

  return (
    <div className="mx-auto max-w-7xl px-4 py-16 sm:px-6">
      {/* Hero */}
      <section className="mb-20 text-center">
        <div className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary/30 bg-primary/10 px-4 py-1.5 text-sm text-primary">
          <Sparkles size={16} />
          {t('common.tagline')}
        </div>
        <h1 className="mb-4 text-4xl font-extrabold leading-tight sm:text-6xl">
          <span className="text-gradient">{t('home.heroTitle')}</span>
        </h1>
        <p className="mx-auto mb-8 max-w-2xl text-lg text-text-secondary">
          {t('home.heroSubtitle')}
        </p>
        <div className="flex flex-wrap items-center justify-center gap-3">
          <Link to="/create">
            <Button size="lg">
              <Sparkles size={20} />
              {t('home.ctaCreate')}
            </Button>
          </Link>
          <Link to="/explore">
            <Button size="lg" variant="outline">
              <Compass size={20} />
              {t('home.ctaExplore')}
            </Button>
          </Link>
        </div>
      </section>

      {/* Modes Grid */}
      <section>
        <div className="mb-8 text-center">
          <h2 className="mb-2 text-3xl font-bold">{t('home.modesTitle')}</h2>
          <p className="text-text-secondary">{t('home.modesSubtitle')}</p>
        </div>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {MODES.map((m) => (
            <Link
              key={m.id}
              to={m.id === 'custom' ? '/custom' : `/create/${m.id}`}
            >
              <Card variant="interactive" padding="lg" className="h-full">
                <div className="mb-3 text-4xl">{m.icon}</div>
                <h3 className="mb-2 text-lg font-bold text-text-primary">
                  {t(`modes.${m.id}.title`)}
                </h3>
                <p className="text-sm text-text-secondary">
                  {t(`modes.${m.id}.description`)}
                </p>
              </Card>
            </Link>
          ))}
        </div>
      </section>
    </div>
  );
}